; The runtime's declarations (the build expands the list: src/runtime/head.txt)
; mput ../../runtime/head.txt
; AUTOINC:BEGIN (do not edit -- managed by scripts/gen-includes.js)
            REL
            use   Locator.Macs
            use   Load.Macs
            use   Mem.Macs
            use   Misc.Macs
            use   Util.Macs
            use   EDS.GSOS.Macs
            use   GTE.Macs.s
            put    ../../Externals.s
            put    ../../core/Defs.s
            put    ../../rom/rom_kbd_macs.s
            put    ../../ImportEngine.s
; AUTOINC:END

            put   Config.s
            put   QuitMode.s                  ; QUIT_*: what Q does (generated by build.js)
            put   pal_defs.s                  ; PAL_* constants from palettes/

            mx    %00

            phk
            plb

; NROM: vertical mirroring at power on.
            tax                           ; X = memory manager user ID (passed in A by GS/OS)
            lda   #VERTICAL_MIRRORING     ; A = cartridge nametable mirroring at power on
            jsr   NES_StartUp

; The C PRG's zero page is linked at $0020, so it has to run with D=$0000.
; The runtime's default DP_NES is in the STKDP bank and would make every
; zeropage access miss.
            lda   #0
            sta   DP_NES

; Select the title palette (also installed by InitPlayfield during NES_StartUp).
            jsr   SetDefaultPalette

; Run the C game's reset code from ROMBase+$FFFC.
            jsr   NES_ColdBoot

            DO    QUIT_AT_BOOT               ; dev only (build.js --autotest): run the quit path at start-up,
            brl   quit                       ; so it can be checked without pressing Q and Y
            FIN

GameStart
            jsr   NES_EvtLoop

            cmp   #USER_SAYS_QUIT
            beq   quit

            cmp   #USER_SAYS_RESET
            bne   quit

            jsr   NES_WarmBoot
            bra   GameStart

; Q, confirmed: leave the game.  What "leave" can mean is a property of the disk, so the build decides
; (QUIT_EXITSCREEN / QUIT_RESTARTS, generated by build.js):
;
;   default (neither flag) is the full System 6 volume, which has a Finder: quitting shuts the runtime
;   down and returns to the desktop ($0000: no next application specified, GS/OS uses its shell).
;
;   QUIT_EXITSCREEN is the one-way exit, and it is what `node build.js --exitscreen`, `npm run make:boot`
;   and the 800 KiB boot disk use: shut the runtime down, repaint the Super Hi-Res screen with a message
;   that says the game has exited, and stop there.  Nothing on that disk can bring the game back, so a
;   reset is the only way out -- which is what the screen tells the user.
;
;   QUIT_RESTARTS is the alternative for a disk the game cannot leave: save the preferences and go back
;   to the title screen.  (`node build.js --boot`; not used by any image the project ships.)
;
; A GS/OS call to look for the Finder on the volume does not work here: from the game, and also from
; the start-up of a program the Finder launched, opening any pathname failed -- the answer was always
; "no Finder", even on a volume that has one.  A build-time switch has no such blind spot.
quit
            DO    QUIT_EXITSCREEN
            brl   QuitToExitScreen
            ELSE
            DO    QUIT_RESTARTS
            bra   RestartGame
            ELSE
            jsr   NES_ShutDown

            _QuitGS    qtRec
qtRec       adrl  $0000
            da    $00
            FIN
            FIN

RestartGame
            jsr   NES_Pause
            jsr   SavePrefData
            jsr   NES_Resume
            jsr   NES_WarmBoot
            brl   GameStart

            DO    QUIT_EXITSCREEN
; The quit screen for the 800 KiB boot disk: the game stops here for good and says so, and only the reset
; button brings the machine back.  This is the whole of the exit code; the picture is data.
;
; Why Super Hi-Res and not a classic 40-column text screen (which is what this routine tried first):
; the machine does switch to the legacy text display, and the page does get written, but the video
; generator reads that page back with an offset and a stride that do not match a plain 40x24 page -- a
; 24-row page came out with two of its rows on every displayed row, shifted left and up -- and none of
; the levers that should change that had any effect ($C00C to drop to 40 columns, $C04A-$C04D to clear
; the fine scroll, a fresh $C029 write, shadow off, both banks filled).  Rather than depend on that, the
; screen is a 320x200 SHR bitmap rendered at build time from the game's own CHR font
; (scripts/make-quit-screen.mjs -> QuitScreen.s, put at the bottom of this file with the other data),
; and this code copies it to video memory.  The display is still SHR at this point: NES_ShutDown restores
; the mode the game started in, which is SHR ($C1), so nothing has to be switched on.
;
; _QuitGS is *not* used, and that is a measured result too: with $0000 the next-application lookup stops
; on "Can't run next application. Error=$1E06" (there is none on this disk), and with our address GS/OS
; does not enter it.  GS/OS has no ProDOS 8 to hand a GS/OS application to, and there is no Finder here.
QuitToExitScreen
            jsr   NES_Pause
            jsr   SavePrefData
            jsr   NES_ShutDown

            mx    %00
            sei                                ; nothing else must touch the display from here on
            sep   #$20
            lda   #$00
            stal  $00C034                      ; border black, so nothing frames the picture

; Palette 0 becomes black (index 0) and white (index 15); the bitmap uses only those two, so no colour
; format question is left open.  The palette words are at $E19E00, 15 * 2 = 30 bytes in for index 15.
            rep   #$20
            lda   #$0000
            stal  $00E19E00
            lda   #$0FFF
            stal  $00E19E1E

; Every scanline shows palette 0: zero the 200 scanline control bytes at $E19D00.
            sep   #$20
            rep   #$10
            ldx   #$0000
:scb        lda   #$00
            stal  $00E19D00,x
            inx
            cpx   #$00C8
            bne   :scb

; Paint the picture: clear the whole 320x200 screen first, then copy the four bands of text rows to the
; pixel rows they were rendered at (scripts/make-quit-screen.mjs).  Nothing is drawn where there is no
; line, so the blank rows cost no data -- which is what keeps this out of a segment of its own.
            phk
            plb                                ; the band data is in this segment
            rep   #$10                         ; X 16-bit, A stays 8-bit
            lda   #$00
            ldx   #$0000
:clear      stal  $00E12000,x
            inx
            cpx   #$7D00                       ; 320 * 200 * 2 / 4 * 2 = 32,000 bytes
            bne   :clear

            ldx   #$0000
:b0         lda   quitBand0,x
            stal  $00E12000+$1900,x            ; pixel row 40
            inx
            cpx   #$0500                       ; 8 rows * 160 bytes
            bne   :b0
            ldx   #$0000
:b1         lda   quitBand1,x
            stal  $00E12000+$2D00,x            ; pixel row 72
            inx
            cpx   #$0500
            bne   :b1
            ldx   #$0000
:b2         lda   quitBand2,x
            stal  $00E12000+$4600,x            ; pixel row 112
            inx
            cpx   #$0500
            bne   :b2
            ldx   #$0000
:b3         lda   quitBand3,x
            stal  $00E12000+$5A00,x            ; pixel row 144
            inx
            cpx   #$0500
            bne   :b3
:halt       bra   :halt
            FIN

; Names of the save and preference files (used by misc/io.s)
SAVE_FILENAME strl '1/ae.sav'
PREF_FILENAME strl '1/ae.prefs'

; Engine callbacks (macros only)
            put   Hooks.s

; ===========================================================================
; Game code
; ===========================================================================
            mx    %00

; Called by NES_StartUp before the ROM's reset code runs.  The generated
; palette code needs its swizzle tables installed before the title is drawn.
InitPlayfield
            jmp   SetDefaultPalette

            mx    %00

; CUSTOM_RENDER_SCREEN.  Gameplay uses one continuous source band: SHR 0-199
; maps to NES 16-215 through the grid's y_offset.  The title/credits keep the
; full renderer and their own vertical lift.
CustomRender ENT
            ldal  LayoutActiveAbs
            and   #$00FF
            bne   :draw

            ldal  OAM_COPY
            beq   :inactive
            lda   #1
            stal  LayoutActiveAbs
            bra   :draw

:inactive
            lda   #31
            stal  YOffsetAbs

            ; The title blinks PRESS START by toggling the horizontal
            ; nametable every 16 frames.  Because this custom renderer draws
            ; the full screen itself, it must latch that scroll before drawing.
            ldal  _ppuscroll_y
            tay
            ldal  _ppuscroll_x
            tax

            ; The title's PRESS START lives on nametable 0; the game's
            ; scroll alternates between the two nametables, but the custom
            ; renderer has to select the page itself.  Use a render counter
            ; so PRESS START really blinks.  Credits scroll with y=8, and the
            ; well-done screen scrolls x=-4; both stay on nametable 0.
            ldal  _ppuscroll_x
            and   #$00FF
            bne   :title_nt0
            ldal  _ppuscroll_y
            and   #$00FF
            bne   :title_nt0
            ldal  titleBlink
            inc
            stal  titleBlink
            and   #$0010
            beq   :title_nt0
            lda   #1
            bra   :title_scroll
:title_nt0
            lda   #0
:title_scroll
            jsl   NES_SetScroll

            lda   #0
            ldx   #200
            jsl   PPU_DrawScreenRange
            lda   #0
            stal  YOffsetAbs
            lda   #0
            sec
            rtl

:draw
            ; The grid renderer draws the playfield from its dirty cells.  Keep
            ; the same source offset for the fallback full renderer.
            lda   #16
            stal  YOffsetAbs
            lda   #0
            clc
            rtl
            mx    %00

titleBlink    dw    0

; Palette management generated from palettes/
            put   pal_transitions.s

; The quit screen's pixel data (scripts/make-quit-screen.mjs): data only, but it stays after the entry
; code all the same -- anything assembled in front of the entry point would move it.
            DO    QUIT_EXITSCREEN
            put   QuitScreen.s
            FIN
            put   palettes.s                ; swizzle tables (was the PALDATA segment)

; Runtime code (the build expands the list: src/runtime/code.txt)
            mput  ../../runtime/code.txt
; AUTOINC:BEGIN (do not edit -- managed by scripts/gen-includes.js)
            put    ../../misc/App.Msg.s
            put    ../../misc/io.s
            put    ../../apu/apu.s
            put    ../../rom/scaffold.s
            put    ../../rom/rom_color.s
            put    ../../rom/rom_helpers.s
            put    ../../rom/rom_input.s
            put    ../../rom/rom_kbd_basic.s
            put    ../../rom/rom_exec.s
            put    ../../rom/rom_config.s
            put    ../../rom/rom_config_setup.s
            put    ../../core/ControlBits.s
            put    ../../core/CoreImpl.s
            put    ../../core/Graphics.s
            put    ../../core/Math.s
            put    ../../core/Memory.s
; AUTOINC:END
